import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Paper,
  Button,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  CircularProgress,
  Container,
  Chip,
  Avatar
} from '@mui/material';
import { 
  Users, 
  DollarSign, 
  Clock, 
  AlertTriangle,
  TrendingUp,
  Calendar,
  Award,
  FileText
} from 'lucide-react';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '../../../firebase/config';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const [stats, setStats] = useState({
    totalEmployees: 0,
    activeEmployees: 0,
    pendingPayroll: 0,
    expiringLicenses: 0,
    todayAttendance: 0,
    pendingReviews: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    initializeAndFetchData();
  }, []);

  const initializeAndFetchData = async () => {
    try {
      // Fetch dashboard stats directly
      await fetchDashboardStats();
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load dashboard data');
    }
  };

  const fetchDashboardStats = async () => {
    try {
      // Fetch employees
      const employeesSnapshot = await getDocs(collection(db, 'employees'));
      const employees = employeesSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      
      const activeEmployees = employees.filter(emp => emp.status === 'active');
      
      // Fetch licenses expiring in next 30 days
      const thirtyDaysFromNow = new Date();
      thirtyDaysFromNow.setDate(thirtyDaysFromNow.getDate() + 30);
      
      const licensesSnapshot = await getDocs(collection(db, 'licenses'));
      const expiringLicenses = licensesSnapshot.docs.filter(doc => {
        const license = doc.data();
        const expiryDate = new Date(license.expiryDate);
        return expiryDate <= thirtyDaysFromNow && expiryDate >= new Date();
      });

      // Fetch actual payroll data
      const payrollSnapshot = await getDocs(collection(db, 'payrolls'));
      const pendingPayrolls = payrollSnapshot.docs.filter(doc => {
        const payroll = doc.data();
        return payroll.status === 'pending' || payroll.status === 'draft';
      });

      // Fetch today's attendance
      const today = new Date().toISOString().split('T')[0];
      const attendanceSnapshot = await getDocs(collection(db, 'attendance'));
      const todayAttendance = attendanceSnapshot.docs.filter(doc => {
        const attendance = doc.data();
        return attendance.date === today && attendance.status === 'present';
      });

      // Fetch pending performance reviews
      const reviewsSnapshot = await getDocs(collection(db, 'performance_reviews'));
      const pendingReviews = reviewsSnapshot.docs.filter(doc => {
        const review = doc.data();
        return review.status === 'pending' || review.status === 'draft';
      });

      setStats({
        totalEmployees: employees.length,
        activeEmployees: activeEmployees.length,
        pendingPayroll: pendingPayrolls.length,
        expiringLicenses: expiringLicenses.length,
        todayAttendance: todayAttendance.length,
        pendingReviews: pendingReviews.length
      });
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    {
      title: 'Total Employees',
      value: stats.totalEmployees,
      icon: Users,
      color: '#1e40af',
      bgColor: '#eff6ff',
      link: '/employees'
    },
    {
      title: 'Active Employees',
      value: stats.activeEmployees,
      icon: TrendingUp,
      color: '#059669',
      bgColor: '#f0fdf4',
      link: '/employees'
    },
    {
      title: 'Pending Payroll',
      value: stats.pendingPayroll,
      icon: DollarSign,
      color: '#d97706',
      bgColor: '#fffbeb',
      link: '/payroll'
    },
    {
      title: 'Expiring Licenses',
      value: stats.expiringLicenses,
      icon: AlertTriangle,
      color: '#dc2626',
      bgColor: '#fef2f2',
      link: '/licenses'
    },
    {
      title: 'Today Attendance',
      value: stats.todayAttendance,
      icon: Clock,
      color: '#7c3aed',
      bgColor: '#faf5ff',
      link: '/attendance'
    },
    {
      title: 'Pending Reviews',
      value: stats.pendingReviews,
      icon: FileText,
      color: '#4338ca',
      bgColor: '#eef2ff',
      link: '/performance'
    }
  ];

  const quickActions = [
    { title: 'Add New Employee', link: '/employees/new', icon: Users },
    { title: 'Process Payroll', link: '/payroll', icon: DollarSign },
    { title: 'Mark Attendance', link: '/attendance', icon: Clock },
    { title: 'License Tracking', link: '/licenses', icon: Award }
  ];

  if (loading) {
    return (
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '400px' 
      }}>
        <CircularProgress size={60} sx={{ color: '#1e40af' }} />
      </Box>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ py: 3 }}>
      {/* Header */}
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        mb: 4 
      }}>
        <Typography 
          variant="h4" 
          sx={{ 
            fontWeight: 'bold', 
            color: '#1e3a8a',
            letterSpacing: '0.5px'
          }}
        >
          HR Dashboard
        </Typography>
        <Button
          variant="contained"
          startIcon={<Users size={20} />}
          sx={{
            background: 'linear-gradient(135deg, #1e40af 0%, #3b82f6 100%)',
            color: 'white',
            px: 3,
            py: 1.5,
            fontWeight: 'bold',
            borderRadius: '10px',
            boxShadow: '0 4px 12px rgba(30, 64, 175, 0.3)',
            '&:hover': {
              background: 'linear-gradient(135deg, #1d4ed8 0%, #2563eb 100%)',
              boxShadow: '0 6px 16px rgba(30, 64, 175, 0.4)',
              transform: 'translateY(-1px)'
            },
            transition: 'all 0.2s ease-in-out'
          }}
        >
          Add New Employee
        </Button>
      </Box>

      {/* Stats Grid */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        {statCards.map((stat, index) => {
          const Icon = stat.icon;
          
          return (
            <Grid item xs={12} sm={6} lg={4} key={index}>
              <Card
                sx={{
                  borderRadius: '16px',
                  boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
                  border: '1px solid #f0f0f0',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: '0 8px 30px rgba(30, 58, 138, 0.15)',
                    borderColor: '#1e40af'
                  }
                }}
              >
                <CardContent sx={{ p: 3 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center' }}>
                    <Avatar
                      sx={{
                        backgroundColor: stat.bgColor,
                        width: 56,
                        height: 56,
                        mr: 2.5
                      }}
                    >
                      <Icon size={28} color={stat.color} />
                    </Avatar>
                    <Box sx={{ flex: 1 }}>
                      <Typography
                        variant="body2"
                        sx={{
                          color: '#6b7280',
                          fontWeight: '500',
                          mb: 0.5,
                          fontSize: '13px',
                          textTransform: 'uppercase',
                          letterSpacing: '0.5px'
                        }}
                      >
                        {stat.title}
                      </Typography>
                      <Typography
                        variant="h3"
                        sx={{
                          fontWeight: 'bold',
                          color: '#1f2937',
                          lineHeight: 1
                        }}
                      >
                        {stat.value}
                      </Typography>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>

      {/* Quick Actions */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: '16px',
          border: '1px solid #f0f0f0',
          mb: 4,
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
        }}
      >
        <Box sx={{ p: 3 }}>
          <Typography
            variant="h6"
            sx={{
              fontWeight: 'bold',
              color: '#1f2937',
              mb: 3,
              fontSize: '18px'
            }}
          >
            Quick Actions
          </Typography>
          <Grid container spacing={2}>
            {quickActions.map((action, index) => {
              const Icon = action.icon;
              return (
                <Grid item xs={12} sm={6} lg={3} key={index}>
                  <Card
                    sx={{
                      borderRadius: '12px',
                      border: '1px solid #e5e7eb',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease-in-out',
                      '&:hover': {
                        backgroundColor: '#f8fafc',
                        borderColor: '#1e40af',
                        transform: 'translateY(-2px)',
                        boxShadow: '0 4px 12px rgba(30, 64, 175, 0.1)'
                      }
                    }}
                  >
                    <CardContent sx={{ p: 2.5 }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <Avatar
                          sx={{
                            backgroundColor: '#f8fafc',
                            width: 40,
                            height: 40,
                            mr: 2
                          }}
                        >
                          <Icon size={20} color="#6b7280" />
                        </Avatar>
                        <Typography
                          variant="body2"
                          sx={{
                            fontWeight: '600',
                            color: '#374151',
                            fontSize: '14px'
                          }}
                        >
                          {action.title}
                        </Typography>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        </Box>
      </Paper>

      {/* Recent Activity */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: '16px',
          border: '1px solid #f0f0f0',
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
        }}
      >
        <Box sx={{ p: 3 }}>
          <Typography
            variant="h6"
            sx={{
              fontWeight: 'bold',
              color: '#1f2937',
              mb: 3,
              fontSize: '18px'
            }}
          >
            Recent Activity
          </Typography>
          <List sx={{ p: 0 }}>
            <ListItem sx={{ py: 3, justifyContent: 'center' }}>
              <ListItemText
                primary="No recent activities"
                secondary="Activity will appear here as you use the system"
                primaryTypographyProps={{
                  fontSize: '14px',
                  fontWeight: '500',
                  color: '#6b7280',
                  textAlign: 'center'
                }}
                secondaryTypographyProps={{
                  fontSize: '12px',
                  color: '#9ca3af',
                  textAlign: 'center'
                }}
              />
            </ListItem>
          </List>
        </Box>
      </Paper>
    </Container>
  );
};

export default Dashboard;